// SPHINCS baseline on the lab node: the shipped KISSVM_SPHINCS_SCRIPT verification core (CHECKSIG of the FORS
// root + 16 HORST rounds of two PROOFs each), run by runscript with a REAL signature generated by Minima's own
// SPHINCS code (java/SphincsBaseline.java). The transaction-message part of the script needs real inputs and
// outputs, so it is measured in-process by the Java harness (1.1.2.6 source build) and reported alongside.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { runscript, nodeVersion, saveReceipt, HERE } from './rpc.mjs';
const node = await nodeVersion();
const dir = process.argv[2];
const inproc = {};
for (const f of ['sphincs_1_1', 'sphincs_2_2', 'sphincs_7_2']) inproc[f] = JSON.parse(readFileSync(join(dir, f + '.json'), 'utf8'));
const j = inproc.sphincs_1_1;
const core = j.script.slice(j.script.indexOf('LET forsrootdata='));
const script = `LET sphincspublickey=${j.publicKey} LET hashedmessage=STATE(102) ` + core;
const state = { ...j.state, 102: j.hashedmessage };
const r = await runscript(script, { state });
console.log('node core:', r.instructions, r.success, r.executionError || '');
// negative control: change the message
const bad = await runscript(script, { state: { ...state, 102: '0x' + 'AB'.repeat(32) } });
console.log('node core, wrong message:', bad.instructions, bad.success);
const kiss = ['// sphincs_baseline_core.kiss',
  '// Purpose: the verification core of Minima\'s shipped KISSVM_SPHINCS_SCRIPT (utils/sphincs/SPHINCSUtils.java:22),',
  '//          with the transaction-message loops replaced by STATE(102) = the hashed message.',
  `// Measured on node ${node.version}: ${r.instructions} instructions, success=${r.success}; wrong message -> success=${bad.success} (${bad.instructions}).`,
  `// Full shipped script in-process (1.1.2.6 build): 1 in/1 out ${inproc.sphincs_1_1.instructions}, 2/2 ${inproc.sphincs_2_2.instructions}, 7/2 ${inproc.sphincs_7_2.instructions} instructions.`,
  `// Signature data in state: ${j.stateBytes} bytes (ports 0-79 HORST rounds, 100 WOTS signature, 101 FORS root). Receipt: measure/receipts/sphincs_baseline.json`,
  '', script.replace(/ (LET|ASSERT|WHILE|ENDWHILE|RETURN) /g, '\n$1 '), ''].join('\n');
writeFileSync(join(HERE, '..', 'kiss', 'sphincs_baseline_core.kiss'), kiss);
saveReceipt('sphincs_baseline', { purpose: 'Baseline: Minima shipped SPHINCS (FORS/HORST + one WOTS CHECKSIG) on-chain verification cost', node, timestamp: new Date().toISOString(),
  nodeCore: { instructions: r.instructions, success: r.success, error: r.executionError, rpcMs: r.rpcMs },
  nodeCoreWrongMessage: { instructions: bad.instructions, success: bad.success },
  inProcessFullScript_1_1_2_6: Object.fromEntries(Object.entries(inproc).map(([k, v]) => [k, { inputs: v.inputs, outputs: v.outputs, instructions: v.instructions, success: v.success }])),
  signatureStateBytes: j.stateBytes,
  structure: '16 HORST rounds x (PROOF of HORST root into FORS root + PROOF of SHA3(secret) into a 65,536-leaf HORST tree, index = 2 bytes of the hashed message) + 1 CHECKSIG (Minima WOTS) of the FORS root',
  chipKeygenLeaves: 16 * 65536 });
